INSERT INTO phone_active_info (
    sn, phone_type, imei1, imei2, model, activated, activate_date, coverage, image_path, active_info, sys_time,
    create_time, create_by, nick_name, update_time, update_by
) VALUES (
             #{sn}, #{phoneType}, #{imei1}, #{imei2}, #{model}, #{activated}, #{activateDate}, #{coverage}, #{imagePath}, #{activeInfo}, #{sysTime},
             #{createTime}, #{createBy}, #{nickName}, #{updateTime}, #{updateBy}
         )

mapper.update:
UPDATE phone_active_info
phone_type = #{phoneType}, imei1 = #{imei1}, imei2 = #{imei2}, model = #{model}, activated = #{activated}, activate_date = #{activateDate}, coverage = #{coverage}, image_path = #{imagePath}, active_info = #{activeInfo}, sys_time = #{sysTime}, update_time = now(), update_by = #{updateBy},
WHERE id = #{id}

mapper.select:
SELECT 
FROM phone_active_info

     AND id = #{id}
     AND sn = #{sn}
     AND phone_type = #{phoneType}
     AND imei1 = #{imei1}
     AND imei2 = #{imei2}
     AND model = #{model}
     AND activated = #{activated}
     AND sys_time = #{sysTime}







     AND create_by = #{createBy}
     AND nick_name like CONCAT('%', #{nickName}, '%')

order by create_time desc

SELECT DATE_FORMAT(COALESCE(NULLIF(sys_time, ''), DATE_FORMAT(create_time, '%Y-%m-%d')), '%Y-%m-%d') AS day, COUNT(*) AS orderCount, SUM(CASE WHEN activated = 1 THEN 1 ELSE 0 END) AS activatedCount FROM phone_active_info WHERE DATE(COALESCE(NULLIF(sys_time, ''), DATE_FORMAT(create_time, '%Y-%m-%d'))) >= STR_TO_DATE(#{startDate}, '%Y-%m-%d') AND DATE(COALESCE(NULLIF(sys_time, ''), DATE_FORMAT(create_time, '%Y-%m-%d'))) <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')
AND create_by = #{createBy}
GROUP BY DATE_FORMAT(COALESCE(NULLIF(sys_time, ''), DATE_FORMAT(create_time, '%Y-%m-%d')), '%Y-%m-%d') ORDER BY day ASC

SELECT 
FROM phone_active_info


        AND create_by = #{createBy}


ORDER BY

         create_time DESC
LIMIT #{limit}
